#!/usr/bin/env node
// Bundle the vendored anatomy geometry kit (studio/vendor/anatomy/src: iso-kit, lathe, tube; MIT, github.com/wheresryan22/anatomy)
// into one classic script, studio/vendor/anatomy/anatomy.js, that our concatenating build can include. Each module runs
// in its own closure (they share helper names like runsOf), so nothing leaks into the page except AN_ISO, AN_LATHE, AN_TUBE.
// Re-run after updating the sources: node studio/tools/anatomy-bundle.mjs
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const DIR = path.join(path.dirname(fileURLToPath(import.meta.url)), '../vendor/anatomy');
const MODS = [
  ['AN_ISO', 'iso-kit.mjs', ''],
  ['AN_LATHE', 'lathe.mjs', 'const { cameraOf, iso, pathOf } = AN_ISO;'],
  ['AN_TUBE', 'tube.mjs', 'const { iso, pathOf } = AN_ISO; const G = AN_LATHE;'],
];

let out = '// ---- anatomy geometry kit (vendored, MIT, github.com/wheresryan22/anatomy); generated by studio/tools/anatomy-bundle.mjs\n';
for (const [name, file, prelude] of MODS) {
  let src = fs.readFileSync(path.join(DIR, 'src', file), 'utf8');
  const names = [];
  src = src.replace(/^import .*$/gm, '');
  // iso-kit's SVG/HTML writers (solidSvg, figureSvg, pageHtml, ISO_CSS...) are not needed on canvas and carry URLs the build forbids
  if (file === 'iso-kit.mjs') src = src.slice(0, src.indexOf('const escape ='));
  src = src.replace(/^export (const|function|let) (\w+)/gm, (_, kind, id) => { names.push(id); return `${kind} ${id}`; });
  if (/^export /m.test(src)) throw new Error(`${file}: unhandled export form`);
  out += `const ${name} = (() => {\n${prelude}\n${src}\nreturn { ${names.join(', ')} };\n})();\n`;
}
fs.writeFileSync(path.join(DIR, 'anatomy.js'), out);
console.log(`wrote ${path.join(DIR, 'anatomy.js')} (${out.split('\n').length} lines)`);
